def validate_architecture(components, flows, threats):
    missing = []
    for component in components:
        required = REQUIRED_CONTROLS.get(component.kind, set())
        missing.extend((component.name, control) for control in required - component.controls)
    for flow in flows:
        if flow.crosses_trust_boundary and not (flow.encrypted and flow.authenticated):
            missing.append((flow.name, 'boundary_protection'))
    for threat in threats:
        if threat.risk_score >= 12 and not (threat.mitigations and threat.test_evidence):
            missing.append((threat.threat_id, 'risk_evidence'))
    return missing
